// Explicit live local-SAM UI check. A fresh browser context imports only the
// synthetic fixture generated by guided-group.gpu.mjs; no user project is used.
import {test} from 'node:test';
import {gpuSkip} from './fixtures/portable-images.mjs';
import assert from 'node:assert/strict';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import path from 'node:path';
import {chromium} from 'playwright';
import {objectRegionContains} from '../public/object-regions.mjs';

test('four real highlighted areas open one shared reference group in the actual local editor',{skip:gpuSkip,timeout:600000},async()=>{
  const base=process.env.ASUN_TEST_BASE_URL||'http://127.0.0.1:48010',qa=path.resolve('qa/guided-group'),fixture=path.join(qa,'four-synthetic-birds.png');
  await mkdir(qa,{recursive:true});
  const status=await fetch(base+'/api/local-detection/status',{signal:AbortSignal.timeout(5000)}).then(response=>response.json());
  assert.equal(status.available,true);assert.equal(status.busy,false);
  const bytes=await readFile(fixture).catch(()=>{throw new Error('Run the opted-in tests/guided-group.gpu.mjs first to create qa/guided-group/four-synthetic-birds.png.');}),hash=createHash('sha256').update(bytes).digest('hex');
  const browser=await chromium.launch({headless:true}),context=await browser.newContext({viewport:{width:1672,height:1150},acceptDownloads:true});
  const page=await context.newPage(),errors=[],responses=[];let calls=0;
  page.on('pageerror',error=>errors.push(error.message));
  page.on('request',request=>{if(request.url()===base+'/api/local-detection'&&request.method()==='POST')calls++;});
  page.on('response',response=>{if(response.url()===base+'/api/local-detection'&&response.request().method()==='POST')responses.push(response);});
  try {
    await page.goto(base);await page.waitForFunction(()=>document.documentElement.dataset.ready==='true');
    await page.locator('#imageInput').setInputFiles({name:'Four birds — shared reference test.png',mimeType:'image/png',buffer:bytes});
    await page.waitForFunction(()=>!document.body.classList.contains('busy')&&document.querySelectorAll('.layer-row').length===1);
    await page.locator('[data-tool="highlight"]').click();
    await page.locator('#brushSize').evaluate(input=>{input.value='10';input.dispatchEvent(new Event('input',{bubbles:true}));});
    const centers=[[180,170],[800,170],[180,590],[800,590]];
    for(const [cx,cy] of centers){
      const box=await page.locator('#board').boundingBox();
      const point=(x,y)=>({x:box.x+x*box.width/1000,y:box.y+y*box.height/760});
      const start=point(cx-95,cy+61),end=point(cx+94,cy-67);
      await page.mouse.move(start.x,start.y);await page.mouse.down();await page.mouse.move(end.x,end.y,{steps:12});await page.mouse.up();
    }
    assert.equal(await page.locator('.layer-row').count(),5);
    assert.match(await page.locator('#detectMarkedArea').innerText(),/4/);
    await page.locator('#detectMarkedArea').click();
    await page.waitForFunction(()=>document.querySelector('#guidedDetectionDialog').open&&!document.querySelector('#confirmGuidedDetection').disabled&&document.querySelector('#guidedDetectionPreview').getAttribute('aria-busy')==='false',null,{timeout:120000});
    assert.equal(await page.locator('#guidedGroupList .guided-group-row').count(),4);
    assert.equal(await page.locator('#guidedGroupList .guided-group-row[data-state="ready"]').count(),4);
    assert.equal(calls,4);assert.equal(await page.locator('#guidedDetectionError').innerText(),'');
    const actual=await Promise.all(responses.map(async response=>{const result=await response.json();return {httpStatus:response.status(),model:result.model,device:result.device,candidates:result.regions.length,elapsedMs:result.elapsedMs};}));
    for(const result of actual){assert.equal(result.httpStatus,200);assert.match(result.device,/cuda|NVIDIA|RTX|GPU/i);}
    await page.mouse.move(40,40);
    // The enabled button fades out of its disabled colors. Capture the finished
    // UI state while leaving continuous decorative animations alone.
    await page.evaluate(async()=>{
      const finite=document.getAnimations().filter(animation=>Number.isFinite(animation.effect?.getComputedTiming().endTime));
      await Promise.all(finite.map(animation=>animation.finished.catch(()=>{})));
    });
    await page.screenshot({path:path.join(qa,'four-birds-live-ui.png'),fullPage:true});
    await page.locator('#confirmGuidedDetection').click();
    await page.locator('#referenceDialog').waitFor({state:'visible'});
    const groupBadge=await page.locator('#referenceAreaLabel').innerText();assert.match(groupBadge,/4/);
    const referenceData=await page.evaluate(async source=>{
      const image=new Image();image.src=source;await image.decode();const canvas=document.createElement('canvas');canvas.width=240;canvas.height=200;
      canvas.getContext('2d').drawImage(image,680,80,240,200,0,0,240,200);return canvas.toDataURL('image/png');
    },`data:image/png;base64,${bytes.toString('base64')}`);
    const referenceBytes=Buffer.from(referenceData.split(',')[1],'base64');
    await writeFile(path.join(qa,'blue-bird-shared-reference.png'),referenceBytes);
    await page.locator('#referenceFileInput').setInputFiles({name:'Blue bird — use for all four.png',mimeType:'image/png',buffer:referenceBytes});
    await page.waitForFunction(()=>!document.body.classList.contains('busy')&&document.querySelectorAll('.reference-gallery-card').length===1);
    await page.locator('#labelComment').fill('Apply this blue bird appearance to all four birds in group 1. Keep their positions and the background unchanged.');
    await page.screenshot({path:path.join(qa,'four-birds-live-shared-reference-ui.png'),fullPage:true});
    await page.locator('#saveReferenceLink').click();await page.locator('#referenceDialog').waitFor({state:'hidden'});
    const pending=page.waitForEvent('download');await page.locator('#saveProject').click();
    const download=await pending,stream=await download.createReadStream(),chunks=[];
    for await(const chunk of stream)chunks.push(chunk);
    const project=JSON.parse(Buffer.concat(chunks).toString()),label=project.layers.find(item=>item.objectRegion?.group);
    assert.equal(label.objectRegion.group.areaCount,4);assert.equal(project.references.length,1);
    const {referenceLinks}=await import('../public/core.mjs');assert.equal(referenceLinks(label).length,1);
    for(const point of centers)assert.equal(objectRegionContains(project,label,point),true);
    assert.equal(objectRegionContains(project,label,[500,380]),false);
    assert.equal(project.layers.filter(item=>item.kind==='drawing'&&item.visible).length,0);
    assert.equal(project.layers.filter(item=>item.kind==='drawing').length,4);
    const savedHash=createHash('sha256').update(Buffer.from(project.assets[project.original.assetId].source.split(',')[1],'base64')).digest('hex');
    assert.equal(savedHash,hash);assert.deepEqual(errors,[]);
    await page.mouse.move(40,40);await page.screenshot({path:path.join(qa,'four-birds-live-group-saved-ui.png'),fullPage:true});
    await writeFile(path.join(qa,'live-ui-20261020.json'),JSON.stringify({status:'passed',endpoint:base,fixture:'Synthetic birds; real local SAM requests through actual editor controls, fresh browser context',requests:calls,results:actual,groupBadge,sharedReferenceCount:1,groupAreas:4,allTargetCentersContained:true,backgroundGapExcluded:true,editableMarksPreserved:4,consumedMarksVisible:0,sourceSha256Before:hash,sourceSha256After:savedHash,pageErrors:errors,screenshots:['four-birds-live-ui.png','four-birds-live-shared-reference-ui.png','four-birds-live-group-saved-ui.png']},null,2));
  } catch(error) {
    await page.screenshot({path:path.join(qa,'four-birds-live-ui-failure.png'),fullPage:true}).catch(()=>{});
    throw error;
  } finally {await context.close();await browser.close();}
});
